/* audio/effects/chain.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "../../context.js";

export function install(P) {


  // Dry/wet stage used by the offline chain. All parameters are constants for
  // the whole render — that is exactly why no real-time automation is needed.
  function makeFxStage(context, processorInput, processorOutput, mix) {
    const level = P.clamp(Number(mix) || 0, 0, 1);
    const input = context.createGain();
    const output = context.createGain();
    const dry = context.createGain();
    const wet = context.createGain();
    dry.gain.value = 1 - level;
    wet.gain.value = level;
    input.connect(dry);
    dry.connect(output);
    input.connect(processorInput);
    processorOutput.connect(wet);
    wet.connect(output);
    return { input, output };
  }

  function connectOfflineFxChain(context, source, destination, settings, oscillators) {
    let node = source;
    const fx = settings.fx;
    if (fx.distortionEnabled) {
      const shaper = context.createWaveShaper();
      shaper.curve = P.makeDistortionCurve(fx.distortionDrive);
      try { shaper.oversample = "4x"; } catch {}
      const tone = context.createBiquadFilter();
      tone.type = "lowpass";
      tone.frequency.value = 600 + P.clamp(fx.distortionTone, 0, 1) * 11400;
      shaper.connect(tone);
      const stage = P.makeFxStage(context, shaper, tone, fx.distortionMix);
      node.connect(stage.input);
      node = stage.output;
    }
    if (fx.saturationEnabled) {
      const shaper = context.createWaveShaper();
      shaper.curve = P.makeSaturationCurve(fx.saturationDrive);
      try { shaper.oversample = "2x"; } catch {}
      const tone = context.createBiquadFilter();
      tone.type = "lowpass";
      tone.frequency.value = 1800 + P.clamp(fx.saturationTone, 0, 1) * 16200;
      shaper.connect(tone);
      const stage = P.makeFxStage(context, shaper, tone, fx.saturationMix);
      node.connect(stage.input);
      node = stage.output;
    }
    if (fx.phaserEnabled) {
      const input = context.createGain();
      const output = context.createGain();
      const depth = P.clamp(fx.phaserDepth, P.FX_RANGES.phaserDepth.min, P.FX_RANGES.phaserDepth.max);
      const feedback = P.clamp(fx.phaserFeedback, P.FX_RANGES.phaserFeedback.min, P.FX_RANGES.phaserFeedback.max);
      const filters = [];
      for (let i = 0; i < 6; i++) {
        const filter = context.createBiquadFilter();
        filter.type = "allpass";
        filter.frequency.value = 200 + depth * 700;
        filter.Q.value = 0.9;
        filters.push(filter);
        if (i === 0) input.connect(filter);
        else filters[i - 1].connect(filter);
      }
      filters[filters.length - 1].connect(output);
      if (feedback > 0) {
        const loop = context.createGain();
        loop.gain.value = feedback;
        filters[filters.length - 1].connect(loop);
        loop.connect(filters[0]);
      }
      const lfo = context.createOscillator();
      lfo.type = "sine";
      lfo.frequency.value = P.clamp(fx.phaserRate, P.FX_RANGES.phaserRate.min, P.FX_RANGES.phaserRate.max);
      const lfoGain = context.createGain();
      lfoGain.gain.value = depth * 900;
      lfo.connect(lfoGain);
      filters.forEach((filter) => lfoGain.connect(filter.frequency));
      lfo.start(0);
      if (oscillators) oscillators.push(lfo);
      const stage = P.makeFxStage(context, input, output, fx.phaserMix);
      node.connect(stage.input);
      node = stage.output;
    }
    if (fx.tremoloEnabled) {
      const trem = context.createGain();
      const depth = P.clamp(fx.tremoloDepth, P.FX_RANGES.tremoloDepth.min, P.FX_RANGES.tremoloDepth.max);
      trem.gain.value = 1 - depth * 0.5;
      const lfo = context.createOscillator();
      lfo.type = "sine";
      lfo.frequency.value = P.clamp(fx.tremoloRate, P.FX_RANGES.tremoloRate.min, P.FX_RANGES.tremoloRate.max);
      const lfoGain = context.createGain();
      lfoGain.gain.value = depth * 0.5;
      lfo.connect(lfoGain);
      lfoGain.connect(trem.gain);
      lfo.start(0);
      if (oscillators) oscillators.push(lfo);
      const stage = P.makeFxStage(context, trem, trem, fx.tremoloMix);
      node.connect(stage.input);
      node = stage.output;
    }
    if (fx.vibratoEnabled) {
      const delay = context.createDelay(0.05);
      const depth = P.clamp(fx.vibratoDepth, P.FX_RANGES.vibratoDepth.min, P.FX_RANGES.vibratoDepth.max);
      delay.delayTime.value = 0.006;
      const lfo = context.createOscillator();
      lfo.type = "sine";
      lfo.frequency.value = P.clamp(fx.vibratoRate, P.FX_RANGES.vibratoRate.min, P.FX_RANGES.vibratoRate.max);
      const lfoGain = context.createGain();
      lfoGain.gain.value = depth * 0.004;
      lfo.connect(lfoGain);
      lfoGain.connect(delay.delayTime);
      lfo.start(0);
      if (oscillators) oscillators.push(lfo);
      const stage = P.makeFxStage(context, delay, delay, fx.vibratoMix);
      node.connect(stage.input);
      node = stage.output;
    }
    if (fx.ringmodEnabled) {
      const ring = context.createGain();
      const depth = P.clamp(fx.ringmodDepth, P.FX_RANGES.ringmodDepth.min, P.FX_RANGES.ringmodDepth.max);
      ring.gain.value = 0;
      const carrier = context.createOscillator();
      carrier.type = "sine";
      carrier.frequency.value = P.clamp(fx.ringmodFreq, P.FX_RANGES.ringmodFreq.min, P.FX_RANGES.ringmodFreq.max);
      const carrierGain = context.createGain();
      carrierGain.gain.value = depth;
      carrier.connect(carrierGain);
      carrierGain.connect(ring.gain);
      carrier.start(0);
      if (oscillators) oscillators.push(carrier);
      const stage = P.makeFxStage(context, ring, ring, fx.ringmodMix);
      node.connect(stage.input);
      node = stage.output;
    }
    if (fx.chorusEnabled) {
      const delay = context.createDelay(0.08);
      const depth = P.clamp(fx.chorusDepth, 0, 1);
      delay.delayTime.value = 0.01 + depth * 0.004;
      const lfo = context.createOscillator();
      lfo.type = "sine";
      lfo.frequency.value = P.clamp(fx.chorusRate, P.FX_RANGES.chorusRate.min, P.FX_RANGES.chorusRate.max);
      const lfoGain = context.createGain();
      lfoGain.gain.value = depth * 0.004;
      lfo.connect(lfoGain);
      lfoGain.connect(delay.delayTime);
      lfo.start(0);
      if (oscillators) oscillators.push(lfo);
      const stage = P.makeFxStage(context, delay, delay, fx.chorusMix);
      node.connect(stage.input);
      node = stage.output;
    }
    if (fx.flangerEnabled) {
      const delay = context.createDelay(0.02);
      const depth = P.clamp(fx.flangerDepth, P.FX_RANGES.flangerDepth.min, P.FX_RANGES.flangerDepth.max);
      delay.delayTime.value = 0.004 + depth * 0.004;
      const lfo = context.createOscillator();
      lfo.type = "sine";
      lfo.frequency.value = P.clamp(fx.flangerRate, P.FX_RANGES.flangerRate.min, P.FX_RANGES.flangerRate.max);
      const lfoGain = context.createGain();
      lfoGain.gain.value = depth * 0.0035;
      lfo.connect(lfoGain);
      lfoGain.connect(delay.delayTime);
      lfo.start(0);
      if (oscillators) oscillators.push(lfo);
      const stage = P.makeFxStage(context, delay, delay, fx.flangerMix);
      node.connect(stage.input);
      node = stage.output;
    }
    if (fx.delayEnabled) {
      const delay = context.createDelay(1);
      const time = P.clamp(fx.delayTime, P.FX_RANGES.delayTime.min, P.FX_RANGES.delayTime.max);
      const feedback = P.clamp(fx.delayFeedback, P.FX_RANGES.delayFeedback.min, P.FX_RANGES.delayFeedback.max);
      delay.delayTime.value = time;
      const feedbackGain = context.createGain();
      feedbackGain.gain.value = feedback;
      const wetMix = context.createGain();
      delay.connect(wetMix);
      delay.connect(feedbackGain);
      feedbackGain.connect(delay);
      const stage = P.makeFxStage(context, delay, wetMix, fx.delayMix);
      node.connect(stage.input);
      node = stage.output;
    }
    if (fx.reverbEnabled) {
      const convolver = context.createConvolver();
      try { convolver.normalize = true; } catch {}
      convolver.buffer = P.makeReverbImpulse(context, fx.reverbDecay);
      const stage = P.makeFxStage(context, convolver, convolver, fx.reverbMix);
      node.connect(stage.input);
      node = stage.output;
    }
    node.connect(destination);
  }
  Object.assign(P, { makeFxStage, connectOfflineFxChain });
}
